3	<script
4	  src="{{ 'results-list.js' | asset_url }}"
5	  type="module"
6	  fetchpriority="low"
7	></script>
8	
9	{% javascript %}
10	  const url = new URL(window.location.href);
11	  if (url.hash) {
12	    document.addEventListener(
13	      'DOMContentLoaded',
14	      () => {
15	        const card = document.getElementById(url.hash.slice(1));
16	        if (card) {
17	          card.scrollIntoView({ behavior: 'instant' });
18	        }
19	      },
20	      { once: true }
21	    );
22	  }
23	{% endjavascript %}
24	
25	{% comment %} We always render this full-width, as the child blocks have width: page/full settings {% endcomment %}
26	<div class="section-background color-{{ section.settings.color_scheme }}"></div>
27	<results-list
28	  class="section product-grid-container color-{{ section.settings.color_scheme }}"
29	  style="--padding-block-start: {{ section.settings.padding-block-start }}px; --padding-block-end: {{ section.settings.padding-block-end }}px;"
30	  section-id="{{ section.id }}"
31	  infinite-scroll="{{ section.settings.enable_infinite_scroll }}"
32	>
33	  {% render 'skip-to-content-link', href: '#ResultsList', text: 'accessibility.skip_to_results_list' %}
34	
35	  <div
36	    class="collection-wrapper grid gap-style{% if section.settings.product_grid_width == 'full-width' %} collection-wrapper--grid-full-width{% endif %}"
37	  >
38	    {% content_for 'block',
39	      type: 'filters',
40	      id: 'filters',
41	      results: collection,
42	      results_size: collection.products_count
43	    %}
44	
45	    {% assign products_per_page = 24 %}
46	
47	    {% if section.settings.enable_infinite_scroll == false %}
48	      {% assign products_per_page = section.settings.products_per_page %}
49	    {% endif %}
50	
51	    {% paginate collection.products by products_per_page %}
52	      {% capture children %}
53	        {% for product in collection.products %}
54	          {% if section.settings.promo_1_position != blank and forloop.index == section.settings.promo_1_position and section.settings.promo_1_image != blank %}
55	            <li class="product-grid__item product-grid__item--promo" data-page="{{ paginate.current_page }}">
56	              {% render 'plp-promo-card',
57	                image: section.settings.promo_1_image,
58	                heading: section.settings.promo_1_heading,
59	                text: section.settings.promo_1_text,
60	                link_text: section.settings.promo_1_link_text,
61	                link_url: section.settings.promo_1_link_url
62	              %}
63	            </li>
64	          {% endif %}
65	          {% if section.settings.promo_2_position != blank and forloop.index == section.settings.promo_2_position and section.settings.promo_2_image != blank %}
66	            <li class="product-grid__item product-grid__item--promo" data-page="{{ paginate.current_page }}">
67	              {% render 'plp-promo-card',
68	                image: section.settings.promo_2_image,
69	                heading: section.settings.promo_2_heading,
70	                text: section.settings.promo_2_text,
71	                link_text: section.settings.promo_2_link_text,
72	                link_url: section.settings.promo_2_link_url
73	              %}
74	            </li>
75	          {% endif %}
76	          <li
77	            id="{{ section.id }}-{{ product.id }}"
78	            class="product-grid__item product-grid__item--{{ forloop.index0 }}"
79	            data-page="{{ paginate.current_page }}"
80	            data-product-id="{{ product.id }}"
81	            ref="cards[]"
82	          >
83	            {% # theme-check-disable %}
84	            {% content_for 'block', type: '_product-card', id: 'product-card', closest.product: product %}
85	            {% # theme-check-enable %}
86	          </li>
87	        {% endfor %}
88	      {% endcapture %}
89	
90	      {% render 'product-grid',
91	        section: section,
92	        children: children,
93	        products: collection.products,
94	        paginate: paginate,
95	        enable_infinite_scroll: section.settings.enable_infinite_scroll
96	      %}
97	    {% endpaginate %}
98	  </div>
99	</results-list>
100	
101	{% style %}
102	  #shopify-section-{{ section.id }} .product-grid__item--promo {
103	    min-height: 534px;
104	  }
105	
106	  #shopify-section-{{ section.id }} product-card .quick-add__button {
107	    opacity: 1;
108	  }
109	
110	  #shopify-section-{{ section.id }} .product-card__content {
111	    overflow: hidden;
112	  }
113	
114	  #shopify-section-{{ section.id }} .product-card__content .rating-wrapper {
115	    padding-inline: 24px;
116	  }
117	
118	  #shopify-section-{{ section.id }} .product-card__content .custom-liquid-block {
119	    padding-inline: 24px;
120	  }
121	
122	  /* Fixed product image ratio to match design (Figma img frame: 426x310) */
123	  #shopify-section-{{ section.id }} product-card .card-gallery {
124	    --gallery-aspect-ratio: 426 / 310 !important;
125	  }
126	
127	  /* Keep the full product visible inside the fixed-ratio frame (no cropping) */
128	  #shopify-section-{{ section.id }} product-card .card-gallery .product-media-container {
129	    --product-media-fit: contain !important;
130	  }
131	
132	  /* Hide the floating quick-add icon over the image — replaced by the Quick View pill below */
133	  #shopify-section-{{ section.id }} product-card .card-gallery .quick-add {
134	    display: none;
135	  }
136	
137	  /* Quick View pill in card content (Figma: red pill, pad 8/16, radius 28, #BC0F0F) */
138	  #shopify-section-{{ section.id }} .plp-quick-view .quick-add {
139	    position: static;
140	    inset: auto;
141	    pointer-events: auto;
142	  }
143	
144	  #shopify-section-{{ section.id }} .plp-quick-view .quick-add__product-form-component .shopify-product-form {
145	    justify-content: flex-start;
146	    align-items: flex-start;
147	  }
148	
149	  /* Always use the "choose" button so the pill opens the quick view modal */
150	  #shopify-section-{{ section.id }} .plp-quick-view add-to-cart-component {
151	    display: none !important;
152	  }
153	
154	  #shopify-section-{{ section.id }} .plp-quick-view .quick-add__button--choose {
155	    display: inline-flex !important;
156	    align-items: center;
157	    justify-content: center;
158	    position: static;
159	    opacity: 1;
160	    height: 32px;
161	    padding: 8px 16px;
162	    background: var(--color-brand-red, #bc0f0f);
163	    color: #ffffff;
164	    border: none;
165	    border-radius: 28px;
166	    backdrop-filter: none;
167	  }
168	
169	  #shopify-section-{{ section.id }} .plp-quick-view .quick-add__button--choose .add-to-cart-text {
170	    display: none;
171	  }
172	
173	  #shopify-section-{{ section.id }} .plp-quick-view .quick-add__button--choose::after {
174	    content: 'Quick View';
175	    font-family: var(--font-accent--family);
176	    font-weight: 400;
177	    font-size: 14px;
178	    line-height: 16px;
179	    text-transform: uppercase;
180	    color: #ffffff;
181	  }
182	
183	  @media screen and (max-width: 749px) {
184	    #shopify-section-{{ section.id }} .product-grid__item--promo {
185	      min-height: 380px;
186	    }
187	  }
188	{% endstyle %}
