1	{%- doc -%}
2	  This snippet is used to render the product grid on collection and search pages.
3	
4	  @param {object} section - The section object
5	  @param {object} paginate - Pagination object
6	  @param {object} products - Array of product objects
7	  @param {string} [title] - Header of the collection or search results
8	  @param {string} children - List or grid of product cards
9	  @param {boolean} [enable_infinite_scroll] - Whether to enable infinite scroll (default: true)
10	{%- enddoc -%}
11	
12	{% capture product_card_size %}
13	  {% render 'util-product-grid-card-size' section: section %}
14	{% endcapture %}
15	{% assign product_card_size = product_card_size | strip %}
16	
17	{% style %}
18	  @media screen and (min-width: 750px) {
19	    {% case section.settings.layout_type %}
20	      {% when 'grid' %}
21	        .product-grid--{{ section.id }}:is(.product-grid--grid) {
22	          --product-grid-columns-desktop: repeat(auto-fill, minmax({{ product_card_size }}, 1fr));
23	        }
24	
25	
26	      {% when 'organic' %}
27	        {% assign large_span = 2 %}
28	        {% assign row_cycle = 3 %}
29	        {% assign product_cycle = row_cycle | times: 2 %}
30	        {% assign right_large_start_col = 3 %}
31	        .product-grid--{{ section.id }}:not([product-grid-view='zoom-out']):is(.product-grid--organic) .product-grid__item:nth-of-type({{ product_cycle }}n + 1) {
32	          grid-column: 1 / span {{ large_span }};
33	        }
34	
35	        .product-grid--{{ section.id }}:not([product-grid-view='zoom-out']):is(.product-grid--organic) .product-grid__item:nth-of-type({{ product_cycle }}n + 2),
36	        .product-grid--{{ section.id }}:not([product-grid-view='zoom-out']):is(.product-grid--organic) .product-grid__item:nth-of-type({{ product_cycle }}n + 5) {
37	          align-self: end;
38	        }
39	
40	        .product-grid--{{ section.id }}:not([product-grid-view='zoom-out']):is(.product-grid--organic) .product-grid__item:nth-of-type({{ product_cycle }}n + {{ product_cycle }}) {
41	          grid-column: {{ right_large_start_col }} / span {{ large_span }};
42	        }
43	
44	        .product-grid--{{ section.id }}:not([product-grid-view='zoom-out']):is(.product-grid--organic) {
45	          --product-grid-columns-desktop: repeat(4, 1fr);
46	        }
47	    {% endcase %}
48	
49	    /* This logic helps prevent displaying one column for an large or extra-large product card size on a small screen. We want it to display at least two columns. */
50	    {% case section.settings.product_card_size %}
51	      {% when 'extra-large' or 'large' %}
52	        @container product-grid (max-width: calc({{ product_card_size }} * 3 + {{ section.settings.columns_gap_horizontal }}px * 2)) {
53	          .product-grid--{{ section.id }}:is(.product-grid--grid) {
54	            --product-grid-columns-desktop: repeat(2, 1fr);
55	          }
56	        }
57	    {% endcase %}
58	
59	    /* When zoomed out, fit as many 100px-wide columns as possible */
60	    .product-grid--{{ section.id }}[product-grid-view='zoom-out'] {
61	      --product-grid-columns-desktop: repeat(auto-fill, minmax(6.25rem, 1fr));
62	    }
63	
64	    .product-grid--{{ section.id }}[product-grid-view='zoom-out'] .product-grid-view-zoom-out--details {
65	      display: block;
66	    }
67	
68	    .product-grid--{{ section.id }}[product-grid-view='zoom-out'] .product-grid__card {
69	      padding-inline-start: var(--zoom-out-padding-inline-start, 0);
70	      padding-inline-end: var(--zoom-out-padding-inline-end, 0);
71	      padding-block-start: var(--zoom-out-padding-block-start, 0);
72	      padding-block-end: var(--zoom-out-padding-block-end, 0);
73	    }
74	  }
75	{% endstyle %}
76	<div
77	  id="ResultsList"
78	  class="
79	    grid main-collection-grid
80	    {%- if section.settings.inherit_color_scheme == false %} color-{{ section.settings.color_scheme }}{% endif %}
81	    {%- if section.settings.product_grid_width == 'full-width' %} collection-wrapper--full-width{% endif %}
82	    {%- if section.settings.full_width_on_mobile == true %} collection-wrapper--full-width-on-mobile{% endif %}
83	    spacing-style
84	  "
85	
86	  style="
87	    --grid--margin--mobile: 0{% if section.settings.product_grid_width == 'centered' and section.settings.full_width_on_mobile == false %} var(--margin-lg){% else %} 0{% endif %};
88	    --grid-column--desktop: var(--{% if section.settings.product_grid_width == 'centered' %}centered{% else %}full-width{% endif %});
89	    --grid-column--mobile: var(--{% if section.settings.full_width_on_mobile %}full-width{% else %}{% if section.settings.product_grid_width == 'centered' %}centered{% else %}full-width{% endif %}{% endif %});
90	    --padding-inline-start: {{ section.settings.padding-inline-start }}px;
91	    --padding-inline-end: {{ section.settings.padding-inline-end }}px;
92	  "
93	>
94	  <div
95	    style="
96	      grid-column: var(--full-width);
97	      --product-grid-gap-mobile: {{ section.settings.columns_gap_vertical | at_most: 12 }}px {{ section.settings.columns_gap_horizontal | at_most: 12 }}px;
98	      --product-grid-gap-desktop: {{ section.settings.columns_gap_vertical }}px {{ section.settings.columns_gap_horizontal }}px;
99	      container-type: inline-size;
100	      container-name: product-grid;
101	    "
102	  >
103	    {% if products.size == 0 %}
104	      <div class="main-collection-grid__empty">
105	        <h2 class="main-collection-grid__empty-title h2">
106	          {{ 'content.no_products_found' | t }}
107	        </h2>
108	        <p>
109	          {{ 'content.use_fewer_filters_html' | t: link: collection.url, class: 'main-collection-grid__empty-link' }}
110	        </p>
111	      </div>
112	    {% else %}
113	      {% if enable_infinite_scroll %}
114	        <span ref="viewMorePrevious"></span>
115	      {% endif %}
116	
117	      {% if title %}
118	        <h4 class="main-collection-grid__title">{{ title }}</h4>
119	      {% endif %}
120	      <ul
121	        class="product-grid product-grid--{{ section.id }} product-grid--{{ section.settings.layout_type }} {% if section.settings.mobile_product_card_size == 'large' %} product-grid-mobile--large{% endif %}"
122	        data-testid="product-grid"
123	        product-grid-view="default"
124	        ref="grid"
125	        role="list"
126	        data-last-page="{{ paginate.pages }}"
127	        data-product-card-size="{{ section.settings.product_card_size }}"
128	        style="--mobile-columns: {% if section.settings.mobile_product_card_size == 'large' %}1{% else %}2{% endif %};"
129	      >
130	        {% comment %}
131	          This script is used to set the grid view on the product grid stored in sessionStorage. Keeping it here helps us prevent seeing the default state.
132	        {% endcomment %}
133	        {% unless request.design_mode %}
134	          <script>
135	            (() => {
136	              const grid = document.querySelector('.product-grid');
137	              if (!grid) return;
138	
139	              const storedLayoutMobile = sessionStorage.getItem('product-grid-view-mobile') || 'default';
140	              const storedLayoutDesktop = sessionStorage.getItem('product-grid-view-desktop') || 'default';
141	
142	              // No need to read the window width if no custom layouts were saved.
143	              if (storedLayoutMobile === 'default' && storedLayoutDesktop === 'default') return;
144	
145	              const storedLayout = window.innerWidth >= 750 ? storedLayoutDesktop : storedLayoutMobile;
146	              if (storedLayout === 'default') return;
147	
148	              grid.setAttribute('product-grid-view', storedLayout);
149	
150	              const options = document.querySelectorAll(
151	                'input[type="radio"][name="grid"], input[type="radio"][name="grid-mobile"]'
152	              );
153	              for (const option of options) {
154	                option.checked = option.value === storedLayout;
155	              }
156	            })();
157	          </script>
158	        {% endunless %}
159	
160	        {{ children }}
161	      </ul>
162	      {% if enable_infinite_scroll != false %}
163	        <span ref="viewMoreNext"></span>
164	      {% else %}
165	        {% render 'pagination-controls', paginate: paginate %}
166	      {% endif %}
167	    {% endif %}
168	  </div>
169	</div>
170	
171	{% stylesheet %}
172	  .product-grid {
173	    --product-grid-gap: var(--product-grid-gap-mobile);
174	    --mobile-columns: 2; /* Default value */
175	
176	    isolation: isolate;
177	
178	    @media screen and (min-width: 750px) {
179	      --product-grid-gap: var(--product-grid-gap-desktop);
180	    }
